// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // We need to force random != 0 (i.e., random == 1) to make the buggy version execute the if-block.
        // Set block.timestamp to a value that, when hashed with block.difficulty, gives an odd result mod 2.
        // For simplicity, we use warp to set a timestamp that yields random == 1.
        vm.warp(123456);
        vm.roll(1); // block.difficulty is 0 in tests by default; adjust if needed.
        // Call play with exactly 10 wei
        address player = address(0x1234);
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();
        // If the random value was 1 (odd hash), the correct contract does nothing, pot stays 10.
        // The buggy contract sets pot = 0. We assert that pot == 10 (reference behavior).
        assertTrue(c.pot() == 10);
    }
}

