pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Force block.timestamp and block.difficulty so that random == 1
        vm.warp(1);
        vm.difficulty(2);

        address player = address(0x1234);
        vm.deal(player, 10 wei);
        vm.prank(player);
        c.play{value: 10 wei}();

        // For the correct contract: random == 1, so condition false, pot remains 10
        // For the buggy contract: random != 0 is true, so condition fires, pot becomes 0
        assertTrue(c.pot() == 10);
    }
}

