pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        // Warp so block.difficulty is predictable: we want first call to lose (random==1), second to win (random==0)
        // Since random = keccak256(abi.encodePacked(block.timestamp, block.difficulty)) % 2
        // We can control timestamps: pick ts1 and ts2 such that hash %2 == 1 then 0
        vm.warp(1);
        vm.deal(alice, 20);
        vm.prank(alice);
        c.play{value: 10}(); // first call, should lose, pot becomes 10

        vm.warp(2);
        vm.prank(alice);
        c.play{value: 10}(); // second call, should win, reference resets pot to 0, bug leaves pot at 10

        // Assert: reference pot == 0, bug pot == 10
        assertTrue(c.pot() == 0);
    }
}

