pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // First, make a losing play (random will be 1)
        vm.warp(1);
        vm.difficulty(2); // This ensures keccak(1,2) % 2 == 1 (losing)
        c.play{value: 10}();
        // Now, make a winning play (random will be 0)
        vm.warp(2);
        vm.difficulty(3); // This ensures keccak(2,3) % 2 == 0 (winning)
        vm.deal(address(this), 100);
        c.play{value: 10}();
        // After the winning play, reference resets pot to 0, buggy leaves it as 10
        assertTrue(c.pot() == 0, "pot should be 0 after winning play in reference");
    }
}

