        // Player1 plays
        vm.deal(address(0x1), 10);
        vm.prank(address(0x1));
        c.play{value: 10}();
        // Player2 plays
        vm.deal(address(0x2), 10);
        vm.prank(address(0x2));
        c.play{value: 10}();
        // Reference bank balance is 2 wei (1 wei per call); buggy bank balance is 0
        assertTrue(address(c).balance == 0, "bank should have 2 wei in reference, 0 in bug");
    }
}

